<style>
.topic-shell{max-width:1280px;margin:0 auto;min-width:0}.topic-shell input:not([type=checkbox]):not([type=hidden]),.topic-shell select,.topic-shell textarea{width:100%;min-width:0;border:1px solid #d1d5db;border-radius:8px;padding:8px 11px;background:#fff;color:#111827}.topic-shell select[multiple]{min-height:86px}.topic-shell p,.topic-shell h1,.topic-shell h2,.topic-shell h3,.topic-shell a,.topic-shell dd{overflow-wrap:anywhere}.topic-shell label{display:block;font-size:14px;font-weight:500;color:#374151;margin-bottom:6px}.topic-shell .topic-button{display:inline-flex;justify-content:center;align-items:center;min-height:44px;padding:8px 15px;border:1px solid #d1d5db;border-radius:8px;background:white;color:#374151;font-size:14px;font-weight:600;gap:6px;cursor:pointer}.topic-shell .topic-button:active{transform:scale(.96)}.topic-shell .topic-button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.topic-shell .topic-primary{background:#2563eb;border-color:#2563eb;color:white}.topic-shell .topic-button:disabled{opacity:.5;cursor:default}.topic-panel{border:1px solid #e5e7eb;border-radius:10px;background:white;padding:24px;min-width:0}.topic-help{font-size:13px;color:#6b7280;line-height:1.65}.topic-error{font-size:13px;color:#b91c1c;margin-top:5px}.topic-row{padding:14px 0;border-bottom:1px solid #e5e7eb;min-width:0}.topic-shell summary{cursor:pointer;font-weight:600;color:#111827;min-height:44px}.topic-shell table{width:100%;text-align:left;font-size:14px}.topic-shell table.topic-list-table{min-width:900px}.topic-list-table th:nth-child(2),.topic-list-table td:nth-child(2){min-width:280px;max-width:360px}.topic-shell th{padding:12px 16px;background:#f9fafb;font-weight:500;color:#6b7280}.topic-shell td{padding:14px 16px;border-top:1px solid #e5e7eb;vertical-align:top}.topic-shell [hidden]{display:none!important}@media(max-width:640px){.topic-panel{padding:16px}.topic-shell .topic-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.topic-shell .topic-actions>*{min-width:0}.topic-shell h1{overflow-wrap:anywhere}}
</style><script>
document.addEventListener('DOMContentLoaded',()=>{let n=0;document.querySelectorAll('.topic-shell label').forEach(label=>{if(label.control)return;const control=label.parentElement?.querySelector('input:not([type=hidden]),select,textarea');if(control){control.id ||= 'topic-field-'+(++n);label.htmlFor=control.id;}});});
</script>